sap.ui.define([
  "sap/ui/core/UIComponent",
  "sap/ui/model/json/JSONModel",
  "sap/ui/Device"
], function (UIComponent, JSONModel, Device) {
  "use strict";

  return UIComponent.extend("my.app.Component", {
    metadata: {
      manifest: "json",
      interfaces: ["sap.ui.core.IAsyncContentCreation"]
    },

    init: function () {
      // 1. Parent init: creates the models and the router from manifest.json
      UIComponent.prototype.init.apply(this, arguments);

      // 2. An extra model, set in code
      const deviceModel = new JSONModel(Device);
      deviceModel.setDefaultBindingMode("OneWay");
      this.setModel(deviceModel, "device");

      // 3. Start routing: reads the current hash and shows the matching view
      this.getRouter().initialize();
    }
  });
});

import UIComponent from "sap/ui/core/UIComponent";
import JSONModel from "sap/ui/model/json/JSONModel";
import Device from "sap/ui/Device";

/**
 * @namespace my.app
 */
export default class Component extends UIComponent {
  public static metadata = {
    manifest: "json",                              // read all config from manifest.json
    interfaces: ["sap.ui.core.IAsyncContentCreation"]
  };

  public init(): void {
    super.init();                                   // creates models + router from the manifest

    const deviceModel = new JSONModel(Device);
    deviceModel.setDefaultBindingMode("OneWay");
    this.setModel(deviceModel, "device");

    this.getRouter().initialize();                  // the router does not start by itself
  }
}

sap.ui.require(["sap/ui/core/Component", "sap/ui/core/ComponentContainer"], function (Component, ComponentContainer) {
  Component.create({
    name: "my.app",
    manifest: true          // 1. load manifest.json first, 2. preload libs + metadata in parallel
  }).then(function (oComponent) {
    new ComponentContainer({ component: oComponent, height: "100%" }).placeAt("content");
  });
});

sap.ui.require(["sap/ui/VersionInfo"], function (VersionInfo) {
  VersionInfo.load().then(function (info) {
    console.log(info.version); // for example "1.120.15"
  });
});

